const HIGH_ENCHANTMENT_THRESHOLD = 5;

const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

// Item surcharges stack: each one whose condition holds contributes its rate.
const ITEM_SURCHARGES: { appliesTo: (item: Item) => boolean; rate: number }[] = [
  { appliesTo: isCursed, rate: 0.5 },
  { appliesTo: isHighlyEnchanted, rate: 0.3 },
];

const itemSurchargeRateOf = (item: Item): number =>
  sum(
    ITEM_SURCHARGES.filter(({ appliesTo }) => appliesTo(item)).map(
      ({ rate }) => rate,
    ),
  );
